country_event = {
	id = ambition.150
	hide_window = yes
	is_triggered_only = yes

	trigger = {
		has_ascension_perk = ap_defender_of_the_galaxy_nomads
		OR = {
			has_federation = yes
			any_playable_country = {
				OR = {
					has_defensive_pact = root
					has_association_status = root
