script:
leader_event = {
	id = ambition.215
	hide_window = yes
	is_triggered_only = yes

	trigger = {
		exists = fleet
		leader_class = commander
		fleet = {
			any_owned_ship = {
				has_ship_flag = paladin_ship
			}
		}
	}

	immediate = {
		fleet = {
			every_owned_ship = {
				set_disabled = no
			}
			if = {
				limit = {
					is_active_resolution = resolution_paladin_direct_command
				}
				set_controller = galactic_custodian
			}
		}

		#Grant Traits
		add_trait = {
			trait = leader_trait_paladin
			show_message = no
		}
		#Grant Class specialization
		random_list = {
			1 = {
				modifier = {
					factor = 0
					OR = {
						has_leader_flag = paladin_logistician
						has_leader_flag = paladin_strategist
						has_leader_flag = paladin_ambusher
						has_leader_flag = paladin_defender
						has_leader_flag = paladin_spearhead
						has_leader_flag = paladin_knight
					}
				}
				add_trait = {
					trait = leader_trait_paladin_ace
					show_message = no
				}
				#we set a flag to remember the subclass if the leader gets demoted then comes back
				set_leader_flag = paladin_ace
			}
			1 = {
				modifier = {
					factor = 0
					OR = {
						has_leader_flag = paladin_ace
						has_leader_flag = paladin_logistician
						has_leader_flag = paladin_ambusher
						has_leader_flag = paladin_defender
						has_leader_flag = paladin_spearhead
						has_leader_flag = paladin_knight
					}
				}
				add_trait = {
					trait = leader_trait_paladin_strategist
					show_message = no
				}
				set_leader_flag = paladin_strategist
			}
			1 = {
				modifier = {
					factor = 0
					OR = {
						has_leader_flag = paladin_ace
						has_leader_flag = paladin_strategist
						has_leader_flag = paladin_logistician
						has_leader_flag = paladin_defender
						has_leader_flag = paladin_spearhead
						has_leader_flag = paladin_knight
					}
				}
				add_trait = {
					trait = leader_trait_paladin_ambusher
					show_message = no
				}
				set_leader_flag = paladin_ambusher
			}
			1 = {
				modifier = {
					factor = 0
					OR = {
						has_leader_flag = paladin_ace
						has_leader_flag = paladin_strategist
						has_leader_flag = paladin_ambusher
						has_leader_flag = paladin_defender
						has_leader_flag = paladin_spearhead
						has_leader_flag = paladin_knight
					}
				}
				add_trait = {
					trait = leader_trait_paladin_logistician
					show_message = no
				}
				set_leader_flag = paladin_logistician
			}
			1 = {
				modifier = {
					factor = 0
					OR = {
						has_leader_flag = paladin_ace
						has_leader_flag = paladin_strategist
						has_leader_flag = paladin_ambusher
						has_leader_flag = paladin_logistician
						has_leader_flag = paladin_spearhead
						has_leader_flag = paladin_knight
					}
				}
				add_trait = {
					trait = leader_trait_paladin_defender
					show_message = no
				}
				set_leader_flag = paladin_defender
			}
			1 = {
				modifier = {
					factor = 0
					owner = { has_origin = origin_toxic_knights }
				}
				modifier = {
					factor = 0
					OR = {
						has_leader_flag = paladin_ace
						has_leader_flag = paladin_strategist
						has_leader_flag = paladin_ambusher
						has_leader_flag = paladin_logistician
						has_leader_flag = paladin_defender
						has_leader_flag = paladin_knight
					}
				}
				add_trait = {
					trait = leader_trait_paladin_spearhead
					show_message = no
				}
				set_leader_flag = paladin_spearhead
			}
			5 = {
				modifier = {
					factor = 0
					owner = { NOT = { has_origin = origin_toxic_knights } }
				}
				modifier = {
					factor = 0
					OR = {
						has_leader_flag = paladin_ace
						has_leader_flag = paladin_strategist
						has_leader_flag = paladin_ambusher
						has_leader_flag = paladin_logistician
						has_leader_flag = paladin_defender
						has_leader_flag = paladin_spearhead
					}
				}
				add_trait = {
					trait = leader_trait_paladin_knight
					show_message = no
				}
				set_leader_flag = paladin_knight
			}
		}
		#Fire Class confirmation event
		leader_event = { id = ambition.216 }
	}
}

