script:
country_event = {
	id = ambition.315
	hide_window = yes
	is_triggered_only = yes

	trigger = {
		has_global_flag = paladin_project_researched
		any_owned_fleet = {
			is_ship_size = paladin_ship
		}
	}

	immediate = {
		if = { #find if there is a councilor with no paladin
			limit = {
				any_country = {
					is_part_of_galactic_council = yes
					NOT = {
						any_owned_fleet = {
							is_ship_size = paladin_ship
						}
					}
				}
			}
			random_country = { #save them
				limit = {
					is_part_of_galactic_council = yes
					NOT = {
						any_owned_fleet = {
							is_ship_size = paladin_ship
						}
					}
				}
				save_event_target_as = new_councillor
			}
			random_owned_fleet = {
				limit = {
					is_ship_size = paladin_ship
				}
				leader = { #unassign paladin
					unassign_leader = this
				}
				set_owner = event_target:new_councillor #transfer ship ownership
				set_controller = event_target:new_councillor
			}
		}
		else = { #should be that council size has been reduced. In that case, disband the palaship.
			every_owned_fleet = { #(every is probably redundant here but eh. Better safe than cheesey)
				limit = {
					is_ship_size = paladin_ship
				}
				leader = { #unassign paladin
					unassign_leader = this
				}
				delete_fleet = this #destroy the palaship
			}
		}
	}
}

